import { Resolver, Query, Mutation, Args, ObjectType, Field, InputType, ID } from '@nestjs/graphql';

@ObjectType()
class Profile {
  @Field(() => ID)
  id: string;

  @Field(() => String)
  displayName: string;

  @Field(() => String, { nullable: true })
  bio: string | null;

  @Field(() => Number)
  viewCount: number;
}

@InputType()
class UpdateProfileInput {
  @Field(() => String, { nullable: true })
  displayName?: string;

  @Field(() => String, { nullable: true })
  bio?: string | null;
}

interface ProfileRepository {
  findById(id: string): Promise<Profile>;
  save(profile: Profile): Promise<Profile>;
  increment(id: string, field: 'viewCount', amount: number): Promise<void>;
}

@Resolver(() => Profile)
class ProfileResolver {
  constructor(private readonly repo: ProfileRepository) {}

  @Query(() => Profile)
  async profile(@Args('id', { type: () => ID }) id: string): Promise<Profile> {
    // Side effect hidden inside a read/query field.
    await this.repo.increment(id, 'viewCount', 1);
    return this.repo.findById(id);
  }

  @Mutation(() => Profile)
  async updateProfile(
    @Args('id', { type: () => ID }) id: string,
    @Args('input') input: UpdateProfileInput,
  ): Promise<Profile> {
    const existing = await this.repo.findById(id);

    const merged: Profile = {
      ...existing,
      displayName: input.displayName ?? existing.displayName,
      bio: input.bio ?? existing.bio,
    };

    return this.repo.save(merged);
  }
}
